#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.0018965249999999961, 0.284186975, -0.16321428], 'basis': [[-0.0, 0.9999999999814106, -6.09745655275315e-06], [0.6349101019687581, 4.71080970646695e-06, 0.7725860226510894], [0.7725860226654514, -3.871336761658574e-06, -0.6349101019569554]], 'axis': [-6.09745655275315e-06, 0.7725860226510894, -0.6349101019569554], 'zmin': -0.10549466572389529, 'zmax': 0.25317296650318766, 'profiles': [{'outer': [[-0.2120195480126633, -0.1616589401752748], [-0.21576840118923063, -0.155126318997043], [-0.21866565857506004, -0.1492030581358068], [-0.22078307183809262, -0.1430116874210633], [-0.22273053126633088, -0.13572339680906131], [-0.22397249011042225, -0.12928825646805955], [-0.22462950715324242, -0.12273124623704251], [-0.2251405252953769, -0.1151260760517899], [-0.2253354852935067, -0.10854467601535468], [-0.2253354852935067, 0.1085436739806098], [-0.2251405252953769, 0.11512507394392989], [-0.22462950715324242, 0.12273022375839453], [-0.22397249011042225, 0.1292872335271337], [-0.22273053126633088, 0.1357223931858927], [-0.22078307183809262, 0.14301065257361972], [-0.21866565857506004, 0.14920204185864605], [-0.21576840118923063, 0.15512528099718964], [-0.2120195480126633, 0.16165792981871493], [-0.20836868775157227, 0.16706928859706432], [-0.20403497087440026, 0.17206626730863253], [-0.1987281688657197, 0.17738012564048533], [-0.19373846215530946, 0.18171895399806148], [-0.1883336454303312, 0.1853752923731116], [-0.18180963926463406, 0.18912912032233506], [-0.17589468500467226, 0.19202980841366052], [-0.16971107813964237, 0.1941504665192835], [-0.16243250094246509, 0.19610050423134015], [-0.15600628754348664, 0.19734367216213936], [-0.14945775139381223, 0.19800180012843344], [-0.14186249740111867, 0.198513677765609], [-0.13529003722077648, 0.19870868567509042], [0.08151037140956102, 0.19870861752819421], [0.08808325009265724, 0.19851360548688562], [0.0956781468547836, 0.198001723075044], [0.10222623772854073, 0.19734359099205728], [0.10865325501076285, 0.1961004190211583], [0.11593188988454434, 0.19415037673323526], [0.12211460841656305, 0.19202971474063105], [0.12803044190691662, 0.18912902293049494], [0.13455439812186978, 0.18537519087987148], [0.13995794388686558, 0.18171884910752695], [0.14494894335807978, 0.17738001761276467], [0.15025575944172154, 0.17206615594482344], [0.15458820535891113, 0.16706917450904685], [0.15824035203170508, 0.16165781343505053], [0.1619891883797927, 0.155125162256982], [0.16488555880937017, 0.149201921297354], [0.16700384633045265, 0.14301053068090808], [0.16895137116115536, 0.13572227006881513], [0.17019242124817327, 0.1292871096294519], [0.1708498863204291, 0.12273009944756846], [0.17136132931441864, 0.11512494931156565], [0.17155583493401172, 0.10854354922594968], [0.17155583493401172, -0.1085448007700148], [0.17136132931441864, -0.11512620068415413], [0.1708498863204291, -0.12273137054786858], [0.17019242124817327, -0.12928838036574136], [0.16895137116115536, -0.13572351992613887], [0.16700384633045265, -0.14301180931377494], [0.16488555880937017, -0.14920317869709887], [0.1619891883797927, -0.15512643773725063], [0.15824035203170508, -0.1616590565589392], [0.15458820535891113, -0.16707042548474177], [0.15025575944172154, -0.17206739404877935], [0.14494894335807978, -0.17738127238064055], [0.13995794388686558, -0.181720110885717], [0.13455439812186978, -0.18537643911323648], [0.12803044190691662, -0.1891302670624735], [0.12211460841656305, -0.1920309552522295], [0.11593188988454434, -0.19415162325954644], [0.10865325501076285, -0.19610166097155093], [0.10222623772854073, -0.1973447990006057], [0.0956781468547836, -0.19800293691759452], [0.08808325009265724, -0.19851482450573388], [0.08151037140956102, -0.198709832464418], [-0.13529003722077648, -0.1987097643175218], [-0.14186249740111867, -0.1985147522270105], [-0.14945775139381223, -0.19800285986420507], [-0.15600628754348664, -0.19734471783052362], [-0.16243250094246509, -0.19610157576136908], [-0.16971107813964237, -0.1941515334734982], [-0.17589468500467226, -0.19203086157920002], [-0.18180963926463406, -0.18913016967063337], [-0.1883336454303312, -0.18537633761999636], [-0.19373846215530946, -0.18172000599518245], [-0.1987281688657197, -0.1773811643529199], [-0.20403497087440026, -0.17206728268497026], [-0.20836868775157227, -0.1670703113967243]], 'holes': []}], 'simplify_tolerance': 7.94837036279017e-05, 'sketch_entity_count': 88}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
